          app="\${GITHUB_REPOSITORY#*/}"
          release="\${GITHUB_SHA}-\${GITHUB_RUN_ID}-\${GITHUB_RUN_ATTEMPT}"
          assets="https://\${SCOUT_PAGES_OWNER}.github.io/\${app}-dist/releases/\${release}"
